css:
.social-container {
  position: relative;
  perspective: 1000px;
}

.social-button {
  position: relative;
  width: 200px;
  height: 80px;
  background: linear-gradient(135deg, #ff3366, #ff6b35);
  border: 4px solid #000;
  box-shadow:
    8px 8px 0 #000,
    16px 16px 0 rgba(255, 51, 102, 0.3);
  cursor: pointer;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transform-style: preserve-3d;
}

.social-button:hover {
  transform: translateZ(20px) rotateX(5deg) rotateY(-5deg);
  box-shadow:
    12px 12px 0 #000,
    24px 24px 0 rgba(255, 51, 102, 0.4),
    0 0 50px rgba(255, 51, 102, 0.6);
}

.button-face {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: inherit;
  transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.button-text {
  color: #000;
  font-weight: 800;
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 rgba(255, 255, 255, 0.3);
  transition: all 0.4s ease;
}

.social-button:hover .button-text {
  opacity: 0;
  transform: translateY(-30px) scale(0.8);
}

.icons-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-around;
  opacity: 0;
  transform: translateY(30px) scale(0.8);
  transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.social-button:hover .icons-container {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.social-icon {
  width: 32px;
  height: 32px;
  fill: #000;
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transform-origin: center;
  filter: drop-shadow(2px 2px 0 rgba(255, 255, 255, 0.3));
}

.social-icon:nth-child(1) {
  animation-delay: 0.1s;
}

.social-icon:nth-child(2) {
  animation-delay: 0.2s;
}

.social-icon:nth-child(3) {
  animation-delay: 0.3s;
}

.social-icon:nth-child(4) {
  animation-delay: 0.4s;
}

.social-button:hover .social-icon {
  animation: iconPop 0.7s cubic-bezier(0.68, -0.55, 0.265, 1.55) forwards;
}

.social-icon:hover {
  transform: scale(0) rotate(15deg);
  fill: #fff;
  filter: drop-shadow(0 0 10px rgba(255, 255, 255, 0.8));
}

@keyframes iconPop {
  0% {
    transform: scale(0) rotate(-180deg);
    opacity: 0;
  }
  50% {
    transform: scale(1.2) rotate(-90deg);
  }
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 1;
  }
}

/* Glitch effect overlay */
.social-button::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.4),
    transparent
  );
  transition: left 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.social-button:hover::before {
  left: 100%;
}

/* Brutalist geometric accent */
.social-button::after {
  content: "";
  position: absolute;
  top: -4px;
  right: -4px;
  width: 20px;
  height: 20px;
  background: #000;
  clip-path: polygon(0 0, 100% 0, 100% 100%);
  border: 1px;
  transition: all 0.6s ease;
}

.social-button:hover::after {
  transform: scale(1) rotate(deg);
  background: rgb(246, 168, 116);
}

/* Pulse effect on container */
.social-container::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  background: rgba(255, 51, 102, 0.1);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  transition: all 0.6s ease;
  z-index: -1;
}

.social-button:hover ~ .social-container::before,
.social-container:hover::before {
  width: 400px;
  height: 400px;
}
